async () => { /* S0 baseline: Brandt is open at -10, Quinn at 0, no call log yet */ 
  const s = window.__test.getState(); const g = s.globals;
  const blog = g.pretext_brandt_desk_call_state;
  return !s.activeMinigame
    && g.brandt_influence === -10 && g.brandt_lockout_until === 0 && g.brandt_lockout_channel === ''
    && g.brandt_reported === false && g.quinn_influence === 0
    && (!blog || !blog.log || blog.log.length === 0);
 }

async () => { /* Q1 Quinn opens pretext-prep, keyboard-owning, Approach is allowed, Close aborts */ 
  const mg = window.MinigameFramework.currentMinigame; const s = mg.getTestState();
  const npc = window.npcManager.getNPC('quinn_desk');
  const begin = mg.container.querySelector('.pretext-begin');
  return s.overlay.sceneType === 'pretext-prep' && s.overlay.closeMode === 'abort'
    && mg.params.requiresKeyboardInput === true && mg.params.disableClose === true
    && s.pretext.callId === 'quinn_floor_call' && s.pretext.character === 'quinn'
    && s.pretext.npcId === 'quinn_desk' && s.pretext.scene === 'person-chat' && s.pretext.canCall === true
    && npc && npc.callId === 'quinn_floor_call'
    && !!begin && begin.disabled === false && /Approach/.test(begin.textContent);
 }

async () => { /* Q2 Space and E do nothing while Quinn prep is open */ 
  const t = window.__test; const mg = window.MinigameFramework.currentMinigame; const a = t.getState();
  const p0 = { x: a.player.x, y: a.player.y };
  for (const k of [' ', 'e', 'E']) await t.minigame.pressKey(k);
  await new Promise(r => setTimeout(r, 300));
  const b = t.getState();
  return b.activeMinigame && b.activeMinigame.id === 'pretext-prep' && window.MinigameFramework.currentMinigame === mg
    && Math.abs(b.player.x - p0.x) < 0.5 && Math.abs(b.player.y - p0.y) < 0.5 && !b.blockingUi
    && mg.getTestState().pretext.callId === 'quinn_floor_call';
 }

async () => { /* Q3 Close and Approach take focus and have no positive tabindex */ 
  const mg = window.MinigameFramework.currentMinigame;
  const btns = [...mg.container.querySelectorAll('button')].filter(e => e.offsetParent !== null && !e.disabled);
  let focusOk = btns.length > 0;
  for (const e of btns) { e.focus(); if (document.activeElement !== e) focusOk = false; }
  const labels = btns.map(e => (e.getAttribute('aria-label') || e.textContent || '').trim());
  return focusOk && btns.every(e => !(e.tabIndex > 0)) && labels.includes('Close') && labels.includes('Approach');
 }

async () => { /* Q4 Close on Quinn prep ends aborted and does not open person-chat */ 
  const t = window.__test; await new Promise(r => setTimeout(r, 300));

  const since = (m) => { const l = t.peekLog(500); let i = -1; l.forEach((e, j) => { if (e.kind === 'note' && e.message === m) i = j; }); return l.slice(i + 1).filter(e => e.kind === 'event'); };

  const evs = since('Q4 close prep');
  const f = evs.find(e => e.event === 'minigame_failed' && e.data && e.data.minigameName === 'PretextPrepMinigame');
  return !!f && f.data.success === false && f.data.result && f.data.result.aborted === true
    && !evs.some(e => e.event === 'minigame_completed')
    && !t.getState().activeMinigame;
 }

