async () => { /* C2 one borrowed-authority line is in the session log and influence has moved */ 
  const t = window.__test;
  const g = () => window.gameState.globalVariables;
  if (Number(g().brandt_lockout_until) > 0) return true;
  const before = (g().pretext_brandt_desk_call_state && g().pretext_brandt_desk_call_state.log || []).length;
  const deadline = Date.now() + 15000;
  while (Date.now() < deadline) {
    const d = t.minigame.getState() && t.minigame.getState().dialogue;
    if (d && d.awaitingChoice) break;
    await new Promise(r => setTimeout(r, 200));
  }
  const picked = await t.minigame.choose('manager said you could');
  if (!picked || picked.ok === false) return false;
  const end = Date.now() + 15000;
  while (Date.now() < end) {
    const log = (g().pretext_brandt_desk_call_state && g().pretext_brandt_desk_call_state.log) || [];
    const locked = Number(g().brandt_lockout_until) > 0;
    const d = t.minigame.getState() && t.minigame.getState().dialogue;
    const choicesBack = !!(d && d.awaitingChoice);
    const still = t.getState().activeMinigame && t.getState().activeMinigame.id === 'phone-chat';
    if (log.length > before && (choicesBack || locked || !still)) return true;
    if (locked) return true;
    await new Promise(r => setTimeout(r, 200));
  }
  return false;
 }

