async () => { /* L5 a locked-out phone shows the refusal and does not open pretext-prep */
  const t = window.__test;
  const btn = document.getElementById('minigame-cancel') || document.getElementById('minigame-close');
  if (btn && t.getState().activeMinigame) btn.click();
  const closed = Date.now() + 5000;
  while (t.getState().activeMinigame && Date.now() < closed) await new Promise(r => setTimeout(r, 100));
  if (t.getState().activeMinigame) return false;
  await t.moveToNear('slice_desk_phone');
  const seen = [];
  const timer = setInterval(() => {
    for (const n of document.querySelectorAll('.notification-message')) {
      const text = n.textContent || '';
      if (text && !seen.includes(text)) seen.push(text);
    }
  }, 50);
  try { await t.interact('slice_desk_phone'); }
  finally { clearInterval(timer); }
  const mg = t.getState().activeMinigame;
  const locked = window.socialInfluence && window.socialInfluence.isLockedOut('brandt', 'phone') === true;
  return locked && seen.some(n => /will not talk/.test(n)) && (!mg || mg.id !== 'pretext-prep');
 }
